-- kanpai is its own OAuth 2.1 authorization server for `/mcp` (ADR-0013): an app registers
-- itself, the owner says yes on a consent screen, and the app holds a refresh token and a
-- string of short-lived access tokens.
--
-- Generated by `drizzle-kit generate` from `db/schema.ts`, then finished by hand with the
-- comments and the trigger that keeps a grant's revocation final. As in 0009, no secret is
-- here — not a code, not a refresh token, not an access token: only their SHA-256s.
--
-- **The access tokens stay in `access_tokens`** (ADR-0009: one table holds every credential
-- the door accepts). They gain the grant they were issued under and when they expire, and the
-- name a live token must not share becomes a rule about the owner's own tokens only.

CREATE TABLE "oauth_clients" (
	"id" text PRIMARY KEY DEFAULT gen_prefixed_id('cli') NOT NULL,
	"name" text DEFAULT 'An assistant' NOT NULL,
	"redirect_uris" text[] NOT NULL,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "oauth_clients_id_is_prefixed" CHECK ("oauth_clients"."id" ~ '^cli_[a-z0-9]+(_[a-z0-9]+)*$'),
	CONSTRAINT "oauth_clients_name_is_not_blank" CHECK ("oauth_clients"."name" = btrim("oauth_clients"."name") and "oauth_clients"."name" <> ''),
	CONSTRAINT "oauth_clients_have_a_redirect_uri" CHECK (cardinality("oauth_clients"."redirect_uris") > 0)
);
--> statement-breakpoint
CREATE TABLE "oauth_codes" (
	"code_hash" text PRIMARY KEY NOT NULL,
	"client_id" text NOT NULL,
	"redirect_uri" text NOT NULL,
	"code_challenge" text NOT NULL,
	"expires_at" timestamp with time zone NOT NULL,
	"used_at" timestamp with time zone,
	"grant_id" text,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "oauth_codes_code_hash_is_a_sha256" CHECK ("oauth_codes"."code_hash" ~ '^[0-9a-f]{64}$'),
	CONSTRAINT "oauth_codes_challenge_is_an_s256" CHECK ("oauth_codes"."code_challenge" ~ '^[A-Za-z0-9_-]{43}$'),
	CONSTRAINT "oauth_codes_grant_only_once_used" CHECK ("oauth_codes"."grant_id" is null or "oauth_codes"."used_at" is not null)
);
