-- **A grant's revocation is final**, as an access token's is (0009): un-revoking one would hand
-- the door back to whoever kept its refresh token. Its refresh hash changes — that is what
-- rotating is — but never on a revoked grant, where a new one would be a refresh token nobody
-- should be able to use.
create function oauth_grants_are_revoked_once() returns trigger
language plpgsql
as $$
begin
  if old.revoked_at is not null and new.revoked_at is distinct from old.revoked_at then
    raise exception 'a revoked grant stays revoked'
      using errcode = 'restrict_violation',
            constraint = 'oauth_grants_revoked_is_final';
  end if;
  if old.revoked_at is not null and new.refresh_hash <> old.refresh_hash then
    raise exception 'a revoked grant is not refreshed'
      using errcode = 'restrict_violation',
            constraint = 'oauth_grants_revoked_is_final';
  end if;
  return new;
end;
$$;
--> statement-breakpoint
comment on function oauth_grants_are_revoked_once() is
  'A revoked grant is never made live again, and its refresh token is never replaced.';
--> statement-breakpoint
create trigger oauth_grants_are_revoked_once
  before update on oauth_grants
  for each row execute function oauth_grants_are_revoked_once();
